INSERT INTO abilities (id, code, name, description) VALUES (1, 'NOABILITY', '---', 'Abilities are disabled.' ), (2, 'STENCH', 'Stench', 'May cause the foe to flinch.' ), (3, 'DRIZZLE', 'Drizzle', 'Summons rain when switched in.' ), (4, 'SPEEDBOOST', 'Speed Boost', 'Its Speed stat is gradually boosted.' ), (5, 'BATTLEARMOR', 'Battle Armor', 'Protects from critical hits.' ), (6, 'STURDY', 'Sturdy', 'Cannot be knocked out with one hit.' ), (7, 'DAMP', 'Damp', 'Prevents self- destructing moves.' ), (8, 'LIMBER', 'Limber', 'Protects from paralysis.' ), (9, 'SANDVEIL', 'Sand Veil', 'Boosts evasion in a sandstorm.' ), (10, 'STATIC', 'Static', 'Contact may cause paralysis.' ), (11, 'VOLTABSORB', 'Volt Absorb', 'Restores HP if hit by Electric moves.' ), (12, 'WATERABSORB', 'Water Absorb', 'Restores HP if hit by Water moves.' ), (13, 'OBLIVIOUS', 'Oblivious', 'Prevents it from being infatuated.' ), (14, 'CLOUDNINE', 'Cloud Nine', 'Eliminates effects of weather.' ), (15, 'COMPOUNDEYES', 'Compound Eyes', 'Boosts the Poké- mon''s accuracy.' ), (16, 'INSOMNIA', 'Insomnia', 'Prevents it from falling asleep.' ), (17, 'IMMUNITY', 'Immunity', 'Prevents it from getting poisoned.' ), (18, 'FLASHFIRE', 'Flash Fire', 'Boosts Fire moves if hit by one.' ), (19, 'SHIELDDUST', 'Shield Dust', 'Blocks additional attack effects.' ), (20, 'OWNTEMPO', 'Own Tempo', 'Prevents it from becoming confused.' ), (21, 'SUCTIONCUPS', 'Suction Cups', 'Negates forced switch-outs.' ), (22, 'INTIMIDATE', 'Intimidate', 'Lowers the foe''s Attack stat.' ), (23, 'SHADOWTAG', 'Shadow Tag', 'Prevents the foe from escaping.' ), (24, 'LEVITATE', 'Levitate', 'Gives immunity to Ground-type moves.' ), (25, 'EFFECTSPORE', 'Effect Spore', 'Contact may cause Par, Psn, or Slp.' ), (26, 'SYNCHRONIZE', 'Synchronize', 'Passes Psn, Par, or Brn to foes.' ), (27, 'CLEARBODY', 'Clear Body', 'Prevents foes from lowering stats.' ), (28, 'NATURALCURE', 'Natural Cure', 'Switch-outs heal status problems.' ), (29, 'LIGHTNINGROD', 'Lightn